<?php declare(strict_types=1); require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/auth_check.php'; require_once __DIR__.'/../includes/helpers.php'; require_login(); require_post_csrf();
$id=(int)($_POST['id']??0);try{$pdo=db();$q=$pdo->prepare('SELECT category_name FROM categories WHERE id=?');$q->execute([$id]);$name=(string)$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(*) FROM items WHERE category_id=?');$q->execute([$id]);if((int)$q->fetchColumn()>0){flash('error','Kategori tidak dapat dihapus karena masih digunakan oleh barang.');}elseif($name!==''){$q=$pdo->prepare('DELETE FROM categories WHERE id=?');$q->execute([$id]);log_activity($pdo,(int)$_SESSION['user_id'],'Menghapus kategori: '.$name);flash('success','Kategori berhasil dihapus.');}}catch(PDOException $e){error_log($e->getMessage());flash('error','Kategori tidak dapat dihapus.');}redirect_to('/pages/categories.php');
